// Test file: src/app/routes/article/article.model.test.ts

import { Article } from './article.model';

describe('Article readingTime calculation', () => {

  describe('Basic readingTime formula validation', () => {
    it('should calculate readingTime using Math.ceil(wordCount / 200) formula', () => {
      const article = new Article();
      article.body = 'word '.repeat(250); // 250 words
      const expectedReadingTime = Math.ceil(250 / 200); // Should be 2
      expect(article.readingTime).toBe(expectedReadingTime);
    });

    it('should return minimum readingTime of 1 for empty article body', () => {
      const article = new Article();
      article.body = '';
      expect(article.readingTime).toBe(1);
    });

    it('should return readingTime of 1 when article body contains less than 200 words', () => {
      const article = new Article();
      article.body = 'word '.repeat(150); // 150 words
      expect(article.readingTime).toBe(1);
    });
  });

  describe('Edge cases for word count boundaries', () => {
    it('should return readingTime of 1 for exactly 200 words', () => {
      const article = new Article();
      article.body = 'word '.repeat(200); // Exactly 200 words
      expect(article.readingTime).toBe(1);
    });

    it('should return readingTime of 2 for 201 words due to Math.ceil', () => {
      const article = new Article();
      article.body = 'word '.repeat(201); // 201 words
      expect(article.readingTime).toBe(2);
    });

    it('should return readingTime of 2 for 400 words', () => {
      const article = new Article();
      article.body = 'word '.repeat(400); // 400 words
      expect(article.readingTime).toBe(2);
    });

    it('should return readingTime of 3 for 401 words due to Math.ceil', () => {
      const article = new Article();
      article.body = 'word '.repeat(401); // 401 words
      expect(article.readingTime).toBe(3);
    });
  });

  describe('Word counting logic with special characters', () => {
    it('should handle multiple spaces correctly in word count', () => {
      const article = new Article();
      article.body = 'word1    word2     word3'; // Multiple spaces between words
      expect(article.readingTime).toBe(1);
    });

    it('should handle newlines correctly in word count', () => {
      const article = new Article();
      article.body = 'word1\n\nword2\nword3'; // Newlines between words
      expect(article.readingTime).toBe(1);
    });

    it('should handle special characters correctly in word count', () => {
      const article = new Article();
      article.body = 'word1, word2. word3! word4?'; // Special punctuation
      expect(article.readingTime).toBe(1);
    });

    it('should return readingTime of 1 for article body with only whitespace', () => {
      const article = new Article();
      article.body = '   \n\n   \t\t   '; // Only whitespace
      expect(article.readingTime).toBe(1);
    });
  });

  describe('ReadingTime recalculation on body update', () => {
    it('should recalculate readingTime when article body is updated', () => {
      const article = new Article();
      article.body = 'word '.repeat(100); // 100 words
      expect(article.readingTime).toBe(1);

      article.body = 'word '.repeat(300); // Update to 300 words
      expect(article.readingTime).toBe(2);
    });
  });

  describe('Large article readingTime calculation', () => {
    it('should calculate readingTime correctly for long articles', () => {
      const article = new Article();
      const wordCount = 10000;
      article.body = 'word '.repeat(wordCount);
      const expectedReadingTime = Math.ceil(wordCount / 200); // Should be 50
      expect(article.readingTime).toBe(expectedReadingTime);
    });
  });

  describe('Invalid readingTime values (should not be allowed)', () => {
    it('should NOT allow readingTime to be zero (minimum is 1)', () => {
      const article = new Article();
      article.body = '';
      expect(article.readingTime).not.toBe(0);
      expect(article.readingTime).toBe(1);
    });

    it('should return integer readingTime values only (no decimals)', () => {
      const article = new Article();
      article.body = 'word '.repeat(350); // 350 words
      const readingTime = article.readingTime;
      expect(Number.isInteger(readingTime)).toBe(true);
      expect(readingTime).toBe(2); // Math.ceil(350/200) = 2
    });
  });
});

